#!/usr/bin/env python3
"""Generate sre's IGNORECASE tables and reference matches (CPython 3.11).

    PYTHONPATH=. ~/cf-test/.venv/bin/python server/internal/rules/testdata/gen_case.py \
        server/internal/rules/pyre_case_table.go server/internal/rules/testdata/icase_reference.json.gz

pyre_case_table.go: _sre.unicode_tolower / the simple upper case that
_sre's sre_upper_unicode uses (first code point of str.upper()) for every
code point where they differ from the identity, and re._casefix._EXTRA_CASES.
icase_reference.json.gz: for every cased code point c, every code point that
'(?i)' + re.escape(c) matches (and '(?ai)' for ASCII letters), and for a list
of set patterns every code point they match (as ranges).
"""
import _sre
import gzip
import json
import re
import sys
from re import _casefix

assert sys.version_info[:2] == (3, 11), sys.version

MAX = 0x110000
POINTS = [c for c in range(MAX) if not 0xD800 <= c <= 0xDFFF]


def upper(c):
    return ord(chr(c).upper()[0])


lower_pairs, upper_pairs = [], []
for c in POINTS:
    lo, up = _sre.unicode_tolower(c), upper(c)
    assert _sre.unicode_iscased(c) == (lo != c or up != c), hex(c)
    if lo != c:
        lower_pairs.append((c, lo))
    if up != c:
        upper_pairs.append((c, up))


def table(name, pairs):
    lines = [f'var {name} = [...]int32{{']
    row = []
    for c, v in pairs:
        row.append(f'0x{c:x}, 0x{v:x},')
        if len(row) == 6:
            lines.append('\t' + ' '.join(row))
            row = []
    if row:
        lines.append('\t' + ' '.join(row))
    lines.append('}')
    return '\n'.join(lines)


extra = sorted(_casefix._EXTRA_CASES.items())
go = [
    '// Code generated by testdata/gen_case.py from CPython ' + sys.version.split()[0] + '; DO NOT EDIT.',
    '',
    'package rules',
    '',
    '// pyLowerPairs: (c, _sre.unicode_tolower(c)) where they differ.',
    table('pyLowerPairs', lower_pairs),
    '',
    '// pyUpperPairs: (c, sre_upper_unicode(c)) where they differ.',
    table('pyUpperPairs', upper_pairs),
    '',
    '// pyExtraCases is re._casefix._EXTRA_CASES.',
    'var pyExtraCases = map[rune][]rune{',
]
for key, values in extra:
    go.append(f'\t0x{key:x}: {{' + ', '.join(f'0x{v:x}' for v in values) + '},')
go.append('}')
with open(sys.argv[1], 'w', encoding='utf-8') as handle:
    handle.write('\n'.join(go) + '\n')

# Reference matches -----------------------------------------------------------

cased = [c for c in POINTS if _sre.unicode_iscased(c)]
haystack = ''.join(map(chr, cased))
literals = []
for c in cased:
    found = sorted({ord(m) for m in re.findall('(?i)' + re.escape(chr(c)), haystack)})
    literals.append([c] + found)
ascii_literals = []
for c in list(range(0x41, 0x5b)) + list(range(0x61, 0x7b)) + [0x130, 0x131, 0x17f, 0x212a]:
    found = sorted({ord(m) for m in re.findall('(?ai)' + re.escape(chr(c)), haystack)})
    ascii_literals.append([c] + found)

ALL = ''.join(map(chr, POINTS))
SETS = [
    r'(?i)[a-z]', r'(?i)[^a-z]', r'(?i)[İ]', r'(?i)[ı]', r'(?i)[i-k]', r'(?i)[\w]', r'(?i)[a\d]', r'(?i)[^\W\d]',
    r'(?i)[ſ]', r'(?i)[ͅ]', r'(?i)[ΐ]', r'(?i)[ß]', r'(?i)[ẞ]', r'(?i)[ǅ]', r'(?i)[ℹ-Ⅿ]', r'(?i)[Ω]',
    r'(?i)[\U00010400]', r'(?i)[\U00010400-\U0001040f]', r'(?i)[A-\U00010400]', r'(?i)[^\U00010428]',
    r'(?i)[\U0001e900-\U0001e943]', r'(?ai)[a-z]', r'(?ai)[k]', r'(?ai)[^k]', r'(?ai)[\U00010400-\U0001040f]',
    r'(?i)[\s]', r'(?i)[a\s]', r'(?i)[^\S]', r'(?i)[^a\S]', r'(?i)[\x00-\x7f]', r'(?i)[Ā-ſ]',
    r'(?i)[Ḁ-῿]', r'(?i)[^\u0000-￿]', r'(?i)[Ⴀ-ჿ]', r'(?i)[Ꭰ-᏿]',
    r'(?i)[ꭰ-ꮿ]', r'(?i)[ᲀ-ᲈ]', r'(?i)[µ]', r'(?i)[ﬅ]', r'(?i)[a-zA-Z0-9_]', r'(?i)[^a-zA-Z0-9_]',
    r'(?i:[a-c])', r'(?i)(?-i:[a-c])', r'(?i)(?a:[k])', r'(?a)(?u:(?i:[k]))', r'(?i)k', r'(?i)[^ß]', r'(?i)[^İ]',
    r'(?i)\w', r'(?i)\W', r'(?i)[\d\D]', r'(?i)[^\d\D]', r'(?i)[\U0001f600]', r'(?i)[ǈ-ǌ]', r'(?i)[Ⓐ-ⓩ]',
]
sets = []
for pattern in SETS:
    found = sorted({ord(m) for m in re.findall(pattern, ALL)})
    ranges = []
    for c in found:
        if ranges and ranges[-1][1] == c - 1:
            ranges[-1][1] = c
        else:
            ranges.append([c, c])
    sets.append({'pattern': pattern, 'ranges': ranges})

# Unassigned in Python's Unicode database (Go's tables are newer): the tests
# do not compare these code points.
import unicodedata
unassigned = []
for c in POINTS:
    if unicodedata.category(chr(c)) == 'Cn':
        if unassigned and unassigned[-1][1] == c - 1:
            unassigned[-1][1] = c
        else:
            unassigned.append([c, c])
data = {'unicode': unicodedata.unidata_version, 'unassigned': unassigned,
        'literals': literals, 'ascii_literals': ascii_literals, 'sets': sets}
with gzip.GzipFile(sys.argv[2], 'wb', mtime=0) as handle:
    handle.write((json.dumps(data, ensure_ascii=True, separators=(',', ':')) + '\n').encode())
